import { readFileSync, writeFileSync } from "node:fs";

// Keep the generated worker usable directly from public/ and in Docker builds.
// Notification display must not wait for HTTP image fetches after Android idle.
const root = new URL("../public/", import.meta.url);
const worker = new URL("cms-sw.js", root);
const encode = name => "data:image/png;base64," + readFileSync(new URL("pwa/" + name, root)).toString("base64");
const assets = [
  "// BEGIN GENERATED NOTIFICATION ASSETS",
  "// Generated by scripts/embed-notification-assets.mjs; edit public/pwa/ originals.",
  `const NOTIFICATION_ICON = ${JSON.stringify(encode("icon-192.png"))};`,
  `const NOTIFICATION_BADGE = ${JSON.stringify(encode("badge-96.png"))};`,
  "// END GENERATED NOTIFICATION ASSETS",
].join("\n");
const source = readFileSync(worker, "utf8");
if (!source.includes("// BEGIN GENERATED NOTIFICATION ASSETS")) throw new Error("Notification asset markers missing");
const updated = source.replace(/\/\/ BEGIN GENERATED NOTIFICATION ASSETS[\s\S]*?\/\/ END GENERATED NOTIFICATION ASSETS/, assets);
if (updated !== source) writeFileSync(worker, updated);
